// Development-only caller and graph oracle; constructor, properties and collection are ASM.
using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
public static class BoomPropertyProbe {
    [StructLayout(LayoutKind.Sequential)] struct Context {public uint Kind,PC,Method,Depth;}
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode)] static extern IntPtr LoadLibraryExW(string p,IntPtr z,uint f);
    [DllImport("kernel32.dll",CharSet=CharSet.Ansi)] static extern IntPtr GetProcAddress(IntPtr m,string n);
    [DllImport("kernel32.dll")] static extern bool FreeLibrary(IntPtr m);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Create(ulong n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Bind(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Destroy(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Roots(out uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Collect(IntPtr h,IntPtr roots,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Layout(uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Field(uint c,uint f);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint Release();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Pointer();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Entry(ref Context c,[In] ulong[] args);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Platform(ref Context c,IntPtr args,IntPtr pool);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Alloc(IntPtr h,ulong bytes,uint refs,uint type);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr PoolCreate(uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolRun(IntPtr p,IntPtr fn,IntPtr input,IntPtr output,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolDestroy(IntPtr p);
    static void Check(bool ok,string s){if(!ok)throw new Exception(s);}
    static IntPtr Open(string p){IntPtr m=LoadLibraryExW(p,IntPtr.Zero,0x1100);Check(m!=IntPtr.Zero,"Property module load failed");return m;}
    static T Fn<T>(IntPtr m,string n){IntPtr p=GetProcAddress(m,n);Check(p!=IntPtr.Zero,"Missing "+n);return Marshal.GetDelegateForFunctionPointer<T>(p);}
    static void ReleaseFrames(IntPtr m){IntPtr p=GetProcAddress(m,"boom_release_trace_pool");if(p!=IntPtr.Zero)Check(Marshal.GetDelegateForFunctionPointer<Release>(p)()==0,"Constructor frame pool still active");}
    static uint BE32(byte[] b,ref int i){uint n=((uint)b[i]<<24)|((uint)b[i+1]<<16)|((uint)b[i+2]<<8)|b[i+3];i+=4;return n;}
    static string[] Reference(string path,out string[] names){byte[] b=File.ReadAllBytes(path);int at=0;Check(BE32(b,ref at)==0x50524f50&&BE32(b,ref at)==1,"Property reference ABI mismatch");int count=checked((int)BE32(b,ref at));names=new string[count];var values=new string[count];for(int i=0;i<count;i++){int n=(b[at]<<8)|b[at+1];at+=2;names[i]=Encoding.UTF8.GetString(b,at,n);at+=n;int len=unchecked((int)BE32(b,ref at));if(len<0){Check(len==-1,"Invalid reference null");continue;}var chars=new char[len];for(int j=0;j<len;j++){chars[j]=(char)((b[at]<<8)|b[at+1]);at+=2;}values[i]=new string(chars);}Check(at==b.Length,"Reference trailing bytes");return values;}
    static string Text(IntPtr v){if(v==IntPtr.Zero)return null;Check(Marshal.ReadInt64(v,-16)==16&&Marshal.ReadInt32(v,-20)==1,"Invalid property String");IntPtr chars=Marshal.ReadIntPtr(v);long bytes=Marshal.ReadInt64(chars,-16);Check(bytes>=0&&(bytes&1)==0&&bytes<65536&&Marshal.ReadInt64(chars,-8)==261,"Invalid UTF16 property data");return Marshal.PtrToStringUni(chars,checked((int)bytes/2));}
    static IntPtr Construct(IntPtr m,Entry entry,uint owner,out Context c){c=new Context();ulong bits=entry(ref c,new ulong[0]);Check(c.Kind==0&&c.Depth==0&&bits!=0,"Original Raw constructor failed: kind="+c.Kind+", method="+c.Method+", pc="+c.PC);IntPtr value=new IntPtr(unchecked((long)bits));Check(Marshal.ReadIntPtr(value,-8)==Fn<Layout>(m,"boom_get_object_layout")(owner),"Raw constructor returned another type");return value;}
    static int Reachable(IntPtr roots,uint count){var live=new HashSet<IntPtr>();var pending=new Stack<IntPtr>();for(int i=0;i<count;i++)pending.Push(Marshal.ReadIntPtr(roots,i*8));while(pending.Count!=0){IntPtr v=pending.Pop();if(v==IntPtr.Zero||!live.Add(v))continue;uint flags=unchecked((uint)Marshal.ReadInt32(v,-24)),refs=unchecked((uint)Marshal.ReadInt32(v,-20));long bytes=Marshal.ReadInt64(v,-16);Check((flags&0xfffffffd)==0xb00b0001&&bytes>=0&&refs<=(ulong)bytes/8&&live.Count<1048576,"Malformed property graph");for(int i=0;i<refs;i++)pending.Push(Marshal.ReadIntPtr(v,i*8));}return live.Count;}
    static void GC(IntPtr m,IntPtr heap,params IntPtr[] extra){IntPtr roots=Fn<Roots>(m,"boom_get_static_roots")(out uint n),all=Marshal.AllocHGlobal(checked(((int)n+extra.Length)*8));try{for(int i=0;i<n;i++)Marshal.WriteIntPtr(all,i*8,Marshal.ReadIntPtr(roots,i*8));for(int i=0;i<extra.Length;i++)Marshal.WriteIntPtr(all,((int)n+i)*8,extra[i]);uint count=checked(n+(uint)extra.Length);int live=Reachable(all,count);Check(Fn<Collect>(m,"boom_heap_collect")(heap,all,count)!=ulong.MaxValue&&Marshal.ReadInt64(heap,56)==live,"Property snapshot/constructor roots were lost or temporary buffers leaked");}finally{Marshal.FreeHGlobal(all);}}
    public static void CheckRaw(string dll,string reference,uint owner,int offset){
        string[] expected=Reference(reference,out string[] names);IntPtr m=Open(dll),heap=IntPtr.Zero;
        try{heap=Fn<Create>(m,"boom_heap_create")(4*1024*1024);Check(heap!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(heap)==1,"Property heap binding failed");var entry=Fn<Entry>(m,"boom_entry");IntPtr raw=Construct(m,entry,owner,out Context c),array=Marshal.ReadIntPtr(raw,offset),pool=Fn<Pointer>(m,"boom_get_property_pool")();Check(array!=IntPtr.Zero&&Marshal.ReadInt64(array,-16)==expected.Length*8L&&Marshal.ReadInt32(array,-20)==expected.Length,"Raw indexed array shape mismatch");Check(Marshal.ReadInt32(pool,8)==2&&Marshal.ReadInt32(pool,12)==0&&Marshal.ReadIntPtr(pool,72)==heap,"Property snapshot was not published against its heap");
            for(int i=0;i<expected.Length;i++){string actual=Text(Marshal.ReadIntPtr(array,i*8));Check(actual==expected[i],"JVM/ASM platform value differs: "+names[i]);}GC(m,heap,raw);
            IntPtr other=Construct(m,entry,owner,out c),second=Marshal.ReadIntPtr(other,offset);Check(other!=raw&&second!=array,"Raw constructor reused its private object/array");IntPtr first=Marshal.ReadIntPtr(array);Marshal.WriteIntPtr(array,IntPtr.Zero);Check(Marshal.ReadIntPtr(second)==first,"Private Raw arrays share mutable slots");GC(m,heap,raw,other);
            string oldDirectory=Directory.GetCurrentDirectory();try{Directory.SetCurrentDirectory(Path.GetTempPath());IntPtr afterChange=Construct(m,entry,owner,out c),unchanged=Marshal.ReadIntPtr(afterChange,offset);for(int i=0;i<expected.Length;i++)Check(Text(Marshal.ReadIntPtr(unchanged,i*8))==expected[i],"Published native property snapshot changed with process working directory");}finally{Directory.SetCurrentDirectory(oldDirectory);}GC(m,heap);
            for(int i=0;i<64;i++){long before=Marshal.ReadInt64(heap,56);Construct(m,entry,owner,out c);Check(Marshal.ReadInt64(heap,56)==before+2,"Hot Raw constructor allocated beyond its required object and private array");GC(m,heap);}Check(Marshal.ReadIntPtr(pool,72)==heap,"Hot constructor changed heap ownership");
        }finally{if(heap!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(heap)!=0,"Property heap destruction failed");FreeLibrary(m);}
    }
    public static void Parallel(string dll,string runtime,string reference,uint owner,int offset){
        string[] expected=Reference(reference,out string[] names);IntPtr m=Open(dll),r=Open(runtime),heap=IntPtr.Zero,pool=IntPtr.Zero,input=IntPtr.Zero,output=IntPtr.Zero;const int n=2049;
        try{heap=Fn<Create>(m,"boom_heap_create")(16*1024*1024);Check(heap!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(heap)==1,"Property worker heap failed");IntPtr metadata=Fn<Pointer>(m,"boom_get_property_pool")();Check(Marshal.ReadInt32(metadata,8)==0,"Property snapshot was prewarmed");pool=Fn<PoolCreate>(r,"boom_pool_create")(8);Check(pool!=IntPtr.Zero,"Property ASM worker pool failed");input=Marshal.AllocHGlobal(n*128);output=Marshal.AllocHGlobal(n*32);
            for(int batch=0;batch<3;batch++){Check(Fn<PoolRun>(r,"boom_pool_run")(pool,GetProcAddress(m,"boom_entry"),input,output,n)==0,"Concurrent Raw constructor batch failed");var objects=new HashSet<IntPtr>();var arrays=new HashSet<IntPtr>();for(int i=0;i<n;i++){IntPtr raw=Marshal.ReadIntPtr(output,i*32);Check(raw!=IntPtr.Zero&&objects.Add(raw)&&Marshal.ReadInt64(output,i*32+8)==0&&Marshal.ReadInt64(output,i*32+16)==0&&Marshal.ReadInt64(output,i*32+24)==0,"Raw constructor/Context crossed worker records");Check(Marshal.ReadIntPtr(raw,-8)==Fn<Layout>(m,"boom_get_object_layout")(owner),"Concurrent constructor changed actual class");IntPtr array=Marshal.ReadIntPtr(raw,offset);Check(arrays.Add(array)&&Marshal.ReadInt64(array,-16)==expected.Length*8L,"Concurrent Raw objects shared private mutable arrays");for(int j=0;j<expected.Length;j++)Check(Text(Marshal.ReadIntPtr(array,j*8))==expected[j],"Concurrent platform value mismatch: "+names[j]);}GC(m,heap);Check(Marshal.ReadInt32(metadata,8)==2&&Marshal.ReadInt32(metadata,12)==0,"Concurrent property snapshot did not settle");}
        }finally{if(pool!=IntPtr.Zero)Check(Fn<PoolDestroy>(r,"boom_pool_destroy")(pool)==0,"Property worker shutdown failed");if(input!=IntPtr.Zero)Marshal.FreeHGlobal(input);if(output!=IntPtr.Zero)Marshal.FreeHGlobal(output);if(heap!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(heap)!=0,"Property worker heap destroy failed");FreeLibrary(m);FreeLibrary(r);}
    }
    public static void OomAndMetadata(string dll,string runtime){
        IntPtr m=Open(dll),r=Open(runtime),heap=IntPtr.Zero,copy=IntPtr.Zero;
        try{heap=Fn<Create>(m,"boom_heap_create")(65536);Check(heap!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(heap)==1,"Property OOM heap failed");IntPtr pool=Fn<Pointer>(m,"boom_get_property_pool")();var platform=Fn<Platform>(m,"boom_platform_properties");var alloc=Fn<Alloc>(r,"boom_heap_alloc");int blocks=0;while(alloc(heap,4096,0,267)!=IntPtr.Zero){Check(++blocks<1000,"Property heap budget exceeded");}while(alloc(heap,0,0,267)!=IntPtr.Zero){Check(++blocks<4096,"Property heap budget exceeded");}var c=new Context{PC=17,Method=41};Check(platform(ref c,IntPtr.Zero,pool)==IntPtr.Zero&&c.Kind==3&&c.PC==17&&c.Method==41&&Marshal.ReadInt32(pool,8)==0&&Marshal.ReadInt32(pool,12)==0&&Marshal.ReadIntPtr(Marshal.ReadIntPtr(pool,40))==IntPtr.Zero,"Cold property OOM left a published/owned partial snapshot");GC(m,heap);c=new Context();IntPtr a=platform(ref c,IntPtr.Zero,pool);Check(a!=IntPtr.Zero&&c.Kind==0&&Marshal.ReadInt32(pool,8)==2,"Property snapshot did not recover after collection");GC(m,heap);
            blocks=0;while(alloc(heap,4096,0,267)!=IntPtr.Zero){Check(++blocks<1000,"Property heap budget exceeded");}while(alloc(heap,0,0,267)!=IntPtr.Zero){Check(++blocks<4096,"Property heap budget exceeded");}c=new Context();Check(platform(ref c,IntPtr.Zero,pool)==IntPtr.Zero&&c.Kind==3&&Marshal.ReadInt32(pool,8)==2,"Fresh-array OOM destroyed the valid property snapshot");GC(m,heap);c=new Context();Check(platform(ref c,IntPtr.Zero,pool)!=IntPtr.Zero&&c.Kind==0,"Property clone did not recover");GC(m,heap);
            copy=Marshal.AllocHGlobal(80);byte[] bytes=new byte[80];Marshal.Copy(pool,bytes,0,80);foreach(int variant in new int[]{0,1,2,3}){Marshal.Copy(bytes,0,copy,80);if(variant==0)Marshal.WriteInt32(copy,4,99);if(variant==1)Marshal.WriteInt32(copy,56,129);if(variant==2)Marshal.WriteInt32(copy,60,1);if(variant==3)Marshal.WriteIntPtr(copy,72,new IntPtr(heap.ToInt64()+16));c=new Context{PC=13,Method=29};Check(platform(ref c,IntPtr.Zero,copy)==IntPtr.Zero&&c.Kind==7&&c.PC==13&&c.Method==29,"Malformed/foreign-heap platform metadata was accepted");}c=new Context{Kind=3,PC=7,Method=19};Check(platform(ref c,IntPtr.Zero,pool)==IntPtr.Zero&&c.Kind==3&&c.PC==7&&c.Method==19,"Platform call overwrote a pending exception");GC(m,heap);
        }finally{if(copy!=IntPtr.Zero)Marshal.FreeHGlobal(copy);if(heap!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(heap)!=0,"Property OOM heap destroy failed");FreeLibrary(m);FreeLibrary(r);}
    }
    public static string[] Constructors(string dll,uint owner,uint escapedField,uint initializedField,int selfOffset,int valueOffset,int wideOffset,int decimalOffset,int baseOffset,uint exceptionClass,string[] inputs){
        IntPtr m=Open(dll),heap=IntPtr.Zero;
        try{heap=Fn<Create>(m,"boom_heap_create")(4*1024*1024);Check(heap!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(heap)==1,"Constructor fixture heap failed");var entry=Fn<Entry>(m,"boom_entry");var output=new List<string>();foreach(string input in inputs){string[] parts=input.Split(' ');bool noArgs=parts[0]=="default";ulong[] args=noArgs?new ulong[0]:new ulong[]{Convert.ToUInt64(parts[1],16),Convert.ToUInt64(parts[2],16),Convert.ToUInt64(parts[3],16)};var c=new Context();ulong bits=entry(ref c,args);Check(c.Depth==0,"Constructor VM invoker leaked guest frame depth");IntPtr escaped=Marshal.ReadIntPtr(Fn<Field>(m,"boom_get_static_field")(owner,escapedField));Check(escaped!=IntPtr.Zero&&Marshal.ReadIntPtr(escaped,-8)==Fn<Layout>(m,"boom_get_object_layout")(owner)&&Marshal.ReadIntPtr(escaped,selfOffset)==escaped,"Constructor did not preserve initialized/escaped actual object");int count=Marshal.ReadInt32(Fn<Field>(m,"boom_get_static_field")(owner,initializedField));string prefix="v";IntPtr pending=IntPtr.Zero;if(c.Kind==0)Check(new IntPtr(unchecked((long)bits))==escaped,"VM constructor did not return its allocated receiver");else{pending=new IntPtr(unchecked((long)bits));Check(c.Kind==16&&pending!=IntPtr.Zero&&Marshal.ReadIntPtr(pending,-8)==Fn<Layout>(m,"boom_get_object_layout")(exceptionClass),"Constructor exception was truncated or replaced");prefix="e java.lang.IllegalArgumentException";}output.Add(prefix+" "+unchecked((uint)Marshal.ReadInt32(escaped,valueOffset)).ToString("x8")+" "+unchecked((ulong)Marshal.ReadInt64(escaped,wideOffset)).ToString("x16")+" "+unchecked((ulong)Marshal.ReadInt64(escaped,decimalOffset)).ToString("x16")+" "+unchecked((uint)Marshal.ReadInt32(escaped,baseOffset)).ToString("x8")+" "+count);GC(m,heap,pending);Check(Marshal.ReadIntPtr(escaped,selfOffset)==escaped,"Escaped partial-constructor object was reclaimed");}return output.ToArray();
        }finally{ReleaseFrames(m);if(heap!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(heap)!=0,"Constructor fixture heap destroy failed");FreeLibrary(m);}
    }
}
